export function getHistoryScenario(id) {
  return HISTORY_SCENARIOS.find((scenario) => scenario.id === id) || null;
}

export function eventsUpTo(scenario, date) {
  return scenario.events.filter((event) => event.date <= date);
}

export function nextEvent(scenario, date) {
  return scenario.events.find((event) => event.date > date) || null;
}
